CREATE TABLE IF NOT EXISTS customer_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customer_addresses (customer_id BIGINT UNSIGNED PRIMARY KEY, recipient VARCHAR(150) NOT NULL DEFAULT '', phone VARCHAR(24) NOT NULL DEFAULT '', address VARCHAR(350) NOT NULL DEFAULT '', neighborhood VARCHAR(120) NOT NULL DEFAULT '', reference_point VARCHAR(350) NOT NULL DEFAULT '', updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_address_customer FOREIGN KEY(customer_id) REFERENCES customer_accounts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE lunch_orders ADD COLUMN customer_id BIGINT UNSIGNED NULL AFTER id;
ALTER TABLE lunch_orders ADD INDEX idx_lunch_orders_customer (customer_id);
ALTER TABLE lunch_orders ADD CONSTRAINT fk_lunch_customer FOREIGN KEY(customer_id) REFERENCES customer_accounts(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS lunch_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, sender ENUM('customer','restaurant') NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_messages_order(id,order_id), CONSTRAINT fk_message_order FOREIGN KEY(order_id) REFERENCES lunch_orders(id) ON DELETE CASCADE, CONSTRAINT fk_message_customer FOREIGN KEY(customer_id) REFERENCES customer_accounts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;